import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-CnDjqotO.js";import"./product-type-bundle-BIefpRwI.js";var l=JSON.parse(`{"path":"/product-bundle/installation.html","title":"Installation","lang":"en-US","frontmatter":{"title":"Installation"},"git":{},"filePathRelative":"product-bundle/installation.md"}`),u={name:`installation.md`},d={start:`3`};function f(c,l,u,f,p,m){let h=t(`RouteLink`);return s(),o(`div`,null,[l[5]||=n(`<h1 id="installation" tabindex="-1"><a class="header-anchor" href="#installation"><span>Installation</span></a></h1><h2 id="requirements" tabindex="-1"><a class="header-anchor" href="#requirements"><span>Requirements</span></a></h2><table><thead><tr><th>Requirement</th><th>Minimum</th></tr></thead><tbody><tr><td>WordPress</td><td>6.4 or newer (tested up to 6.9)</td></tr><tr><td>PHP</td><td>7.4 or newer</td></tr><tr><td>WooCommerce</td><td>Installed <strong>and active</strong> — the plugin stays dormant without it</td></tr></tbody></table><p>The plugin is compatible with WooCommerce <strong>High-Performance Order Storage (HPOS)</strong> and with the block-based cart and checkout.</p><h2 id="install-the-plugin" tabindex="-1"><a class="header-anchor" href="#install-the-plugin"><span>Install the plugin</span></a></h2><ol><li>Download the <strong>bundle-products-for-woocommerce</strong> plugin ZIP.</li><li>In WordPress admin, go to <strong>Plugins → Add New → Upload Plugin</strong>.</li><li>Choose the ZIP file and click <strong>Install Now</strong>.</li><li>When the installation finishes, click <strong>Activate Plugin</strong>.</li></ol><p>You can also install it manually by extracting the ZIP into <code>wp-content/plugins/</code> and activating <strong>Product Bundle for WooCommerce</strong> from the <strong>Plugins</strong> screen.</p><h2 id="what-activation-does" tabindex="-1"><a class="header-anchor" href="#what-activation-does"><span>What activation does</span></a></h2><p>Activation is intentionally light:</p><ul><li>Registers the <strong>Bundle Product</strong> type so it appears in the product editor&#39;s <strong>Product data</strong> dropdown.</li><li>Stores its version option and schedules a permalink refresh.</li></ul><p>No database tables are created, no user roles are added and no demo content is installed.</p><div class="hint-container warning"><p class="hint-container-title">WooCommerce must be active</p><p>If WooCommerce is missing or deactivated, the plugin simply does nothing — no menus, no product type, no errors. Activate WooCommerce and the Bundle Product type appears immediately.</p></div><h2 id="after-installation" tabindex="-1"><a class="header-anchor" href="#after-installation"><span>After installation</span></a></h2><p>There is <strong>no settings page</strong> — all configuration happens on individual products:</p><ol><li>Go to <strong>Products → Add New</strong> (or edit an existing product).</li><li>In the <strong>Product data</strong> dropdown, choose <strong>Bundle Product</strong>.</li></ol><p><img src="/bundle-products-for-woocommerce/images/product-bundle/product-type-bundle.webp" alt="Choosing the Bundle Product type"></p>`,16),i(`ol`,d,[i(`li`,null,[l[1]||=e(`Configure the new `,-1),l[2]||=i(`strong`,null,`Bundle Items`,-1),l[3]||=e(` tab — the next chapter, `,-1),a(h,{to:`/product-bundle/creating-a-bundle.html`},{default:r(()=>[...l[0]||=[e(`Creating a Bundle`,-1)]]),_:1}),l[4]||=e(`, walks through every field.`,-1)])]),l[6]||=i(`h2`,{id:`updating-and-uninstalling`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#updating-and-uninstalling`},[i(`span`,null,`Updating and uninstalling`)])],-1),l[7]||=i(`ul`,null,[i(`li`,null,[i(`strong`,null,`Updating`),e(` follows the normal WordPress plugin update flow; bundle configuration is stored as product meta and survives updates.`)]),i(`li`,null,[i(`strong`,null,`Deactivating or deleting`),e(` the plugin does not delete your data: bundle products remain as products (their type and item configuration stay stored in the database), so reinstalling the plugin restores full functionality. While the plugin is inactive, bundle product pages no longer show the bundle box or add-to-cart form.`)])],-1)])}var p=c(u,[[`render`,f]]);export{l as _pageData,p as default};